import osimport numpy as npimport matplotlib.pyplot as pltimport tensorflow as tffrom tensorflow.keras.layers import Dense, Flattenfrom tensorflow.keras.models import Modelfrom tensorflow.keras.applications.resnet50 import ResNet50from tensorflow.keras.preprocessing.image import ImageDataGeneratorfrom glob import globfrom keras.callbacks import ModelCheckpoint, ReduceLROnPlateau, EarlyStoppingfrom matplotlib import pyplot as plttrain_images_folder = "./kaggle/chest_xray/train"classes = os.listdir(train_images_folder)num_of_classes = len(classes)model = tf.keras.models.load_model("./pneunomia_smart_model.keras")print("model loaded\n")def prepare_image(path_for_image):    image = tf.keras.utils.load_img(path_for_image, target_size=(224,224))    img_result = tf.keras.utils.img_to_array(image)    img_result = np.expand_dims(img_result, axis = 0)    img_result = img_result / 255.    return img_resultarray_img_names = glob("./kaggle/chest_xray/test/PNEUMONIA/*")print(array_img_names)result_array = []print("model predicting\n")for img_name in array_img_names:    img_for_model = prepare_image(img_name)    result_to_img = model.predict(img_for_model, verbose = 1)    result_array.append(result_to_img)answer_arr = []for answer in result_array:    answer_arr.append(np.argmax(answer, axis = 1))answer_arr = np.array(answer_arr).flatten()recall = (sum(answer_arr)) / len(answer_arr)print("recall - ", recall)